package com.theone.tv;
import android.content.Context;import android.util.*;import org.json.*;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;
final class MediaRepository {
 private final File dir;private final JSONObject primary,secondary;private volatile int successful=2;
 MediaRepository(Context c)throws Exception{dir=new File(c.getFilesDir(),"catalogs");dir.mkdirs();primary=config(c,"private_xtream_primary.json");secondary=config(c,"private_xtream_secondary.json");}
 private JSONObject config(Context c,String name)throws Exception{try(InputStream in=c.getAssets().open(name)){JSONObject value=new JSONObject(read(in));for(String key:new String[]{"server","username","password"})if(value.optString(key).isEmpty())throw new IOException("Source unavailable");return value;}}
 private static String read(InputStream in)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>8*1024*1024)throw new IOException("Response exceeds limit");}return out.toString("UTF-8");}
 private static String enc(String s)throws Exception{return URLEncoder.encode(s,"UTF-8").replace("+","%20");}
 private String api(JSONObject source,String action)throws Exception{return source.getString("server")+"/player_api.php?username="+enc(source.getString("username"))+"&password="+enc(source.getString("password"))+"&action="+action;}
 private HttpURLConnection connect(String url)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(8000);c.setReadTimeout(15000);return c;}
 private Map<String,String> categories(JSONObject source){Map<String,String> names=new HashMap<>();HttpURLConnection c=null;try{c=connect(api(source,"get_live_categories"));if(c.getResponseCode()==200){JSONArray rows=new JSONArray(read(c.getInputStream()));for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row!=null)names.put(row.optString("category_id"),row.optString("category_name"));}}}catch(Exception ignored){}finally{if(c!=null)c.disconnect();}return names;}
 private AtomicFile cache(){return new AtomicFile(new File(dir,"live-v1.bin"));}
 private List<CatalogEntry> cached(){try(InputStream in=cache().openRead()){return CatalogCodec.read(in,"live");}catch(Exception ignored){return Collections.emptyList();}}
 private void save(List<CatalogEntry> rows){AtomicFile file=cache();FileOutputStream out=null;try{out=file.startWrite();CatalogCodec.write(out,rows);file.finishWrite(out);}catch(Exception ignored){if(out!=null)file.failWrite(out);}}
 void load(String type,ProgressiveCatalog.Listener listener)throws Exception{if(!type.equals("live"))throw new IOException("Live TV only");List<ProgressiveCatalog.Source> sources=Arrays.asList(preview->source(primary,false,preview),preview->source(secondary,true,preview));ProgressiveCatalog.loadStreaming(sources,cached(),(rows,complete,count)->{successful=count;listener.update(rows,complete,count);if(count>0)save(rows);});}
 private List<CatalogEntry> source(JSONObject source,boolean second,ProgressiveCatalog.Preview preview)throws Exception{Map<String,String> countries=categories(source);HttpURLConnection c=connect(api(source,"get_live_streams"));List<CatalogEntry> rows=new ArrayList<>();try{if(c.getResponseCode()!=200)throw new IOException("Channels unavailable");try(JsonReader reader=new JsonReader(new InputStreamReader(c.getInputStream(),StandardCharsets.UTF_8))){reader.beginArray();while(reader.hasNext()){if(Thread.currentThread().isInterrupted())throw new IOException("Cancelled");int id=0;String title="",poster="",category="";reader.beginObject();while(reader.hasNext()){String key=reader.nextName();if(reader.peek()==JsonToken.NULL){reader.nextNull();continue;}switch(key){case "stream_id":try{id=Integer.parseInt(reader.nextString());}catch(NumberFormatException ignored){}break;case "name":title=reader.nextString();break;case "stream_icon":poster=reader.nextString();break;case "category_id":category=reader.nextString();break;default:reader.skipValue();}}reader.endObject();if(id<=0||id>=1000000000||title.isEmpty())continue;if(second)id+=1000000000;poster=PosterMetadata.resolve(poster,source.getString("server"));String country=CatalogEntry.country(title,countries.get(category));rows.add(new CatalogEntry(id,title,"m3u8",poster,country,"live",0));rows.add(new CatalogEntry(id,title,"ts",poster,country,"live",0));if(rows.size()==128)preview.accept(new ArrayList<>(rows));}reader.endArray();}}finally{c.disconnect();}return rows;}
 String stream(CatalogEntry entry){if(!entry.type.equals("live"))throw new IllegalArgumentException("Live TV only");JSONObject source=entry.id>=1000000000?secondary:primary;int id=entry.id>=1000000000?entry.id-1000000000:entry.id;try{return source.getString("server")+"/live/"+enc(source.getString("username"))+"/"+enc(source.getString("password"))+"/"+id+"."+entry.extension;}catch(Exception e){throw new IllegalStateException("Source unavailable");}}
 Map<String,String> headersForUri(String uri){return Collections.emptyMap();}
 List<String> posters(CatalogEntry e){return Collections.emptyList();}void clearPosterCache(){}boolean partialSources(){return successful<2;}
}
